Approach: branch once on `iscoroutinefunction` and return an async wrapper that awaits inside the `try`, or a sync wrapper. Sleep functions are parameters so tests do not wait. The tests were run against this implementation.

**`resilience.py`**

```python
from __future__ import annotations

import asyncio
import functools
import inspect
import time
from collections.abc import Callable
from typing import Any


def retry(
    attempts: int = 3,
    on: tuple[type[BaseException], ...] = (ConnectionError, TimeoutError),
    backoff_s: float = 0.0,
    sleep: Callable[[float], Any] = time.sleep,
    asleep: Callable[[float], Any] = asyncio.sleep,
):
    """Retry a sync or async callable. `sleep`/`asleep` are injectable so tests never wait."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorate(fn):
        if inspect.iscoroutinefunction(fn):
            @functools.wraps(fn)
            async def awrapper(*args, **kwargs):
                for attempt in range(1, attempts + 1):
                    try:
                        return await fn(*args, **kwargs)
                    except on:
                        if attempt == attempts:
                            raise
                        await asleep(backoff_s * 2 ** (attempt - 1))
            return awrapper

        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for attempt in range(1, attempts + 1):
                try:
                    return fn(*args, **kwargs)
                except on:
                    if attempt == attempts:
                        raise
                    sleep(backoff_s * 2 ** (attempt - 1))
        return wrapper

    return decorate
```

**`test_resilience.py`**

```python
import asyncio
import inspect
import pytest
from resilience import retry


def test_sync_retries_then_succeeds():
    calls, naps = [], []

    @retry(attempts=3, backoff_s=0.5, sleep=naps.append)
    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise ConnectionError
        return "ok"

    assert flaky() == "ok" and len(calls) == 3 and naps == [0.5, 1.0]


def test_sync_gives_up_and_reraises_last():
    @retry(attempts=2, sleep=lambda s: None)
    def always():
        raise TimeoutError("t")

    with pytest.raises(TimeoutError, match="t"):
        always()


def test_async_is_really_retried():
    calls = []

    @retry(attempts=3, asleep=lambda s: asyncio.sleep(0))
    async def fetch():
        calls.append(1)
        if len(calls) < 3:
            raise ConnectionError
        return "ok"

    assert asyncio.run(fetch()) == "ok" and len(calls) == 3
    assert inspect.iscoroutinefunction(fetch)


def test_metadata_preserved():
    @retry()
    def embed(text: str) -> list[float]:
        """Embed."""
        return [1.0]

    assert embed.__name__ == "embed" and embed.__doc__ == "Embed."


def test_other_exceptions_not_retried():
    calls = []

    @retry(attempts=3)
    def bug():
        calls.append(1)
        raise KeyError

    with pytest.raises(KeyError):
        bug()
    assert len(calls) == 1


def test_bad_attempts():
    with pytest.raises(ValueError):
        retry(attempts=0)
```

